const data = $input.first().json.data;
const resultObject = typeof data.resultObject === 'string' 
  ? JSON.parse(data.resultObject) 
  : data.resultObject;

return [{
  json: {
    resultUrl: resultObject.jsonUrl || resultObject.csvURL,
    agentStatus: data.agentStatus,
    config: $('Client Config').first().json
  }
}];

// === ICP SCORING ENGINE (self-contained for n8n) ===
const config = $('Client Config').first().json;

// ICP Configuration — parametrizable per client
const ICP = {
  titles: {
    hot: ['gerente de ventas', 'director comercial', 'vp sales', 'vp ventas',
      'chief revenue', 'cro', 'head of sales', 'director de ventas',
      'sales director', 'regional sales manager', 'vp of sales'],
    warm: ['gerente comercial', 'sales manager', 'jefe de ventas',
      'country manager', 'gerente general', 'ceo', 'director general',
      'business development', 'desarrollo de negocios', 'gerente de operaciones',
      'managing director', 'cofundador', 'co-founder', 'founder']
  },
  industries: {
    hot: ['information technology', 'computer software', 'internet',
      'financial services', 'management consulting', 'marketing',
      'staffing', 'human resources', 'insurance', 'telecommunications'],
    warm: ['logistics', 'mechanical', 'automotive', 'retail',
      'wholesale', 'food', 'pharmaceutical', 'consumer goods', 'banking']
  },
  locations: {
    premium: ['santiago', 'las condes', 'providencia', 'vitacura'],
    standard: ['chile']
  },
  weights: { title: 40, industry: 25, location: 15, dataQuality: 10 },
  thresholds: { hot: config.hotThreshold || 80, warm: config.warmThreshold || 50, nurture: 20 }
};

function scoreLead(l) {
  let score = 0;
  const title = (l.jobTitle || l.headline || '').toLowerCase();
  const industry = (l.industry || '').toLowerCase();
  const location = (l.location || '').toLowerCase();
  const signals = [];
  const risks = [];

  // Title scoring
  let titleMatch = false;
  for (const t of ICP.titles.hot) {
    if (title.includes(t)) {
      score += ICP.weights.title;
      signals.push('Cargo ideal: ' + t);
      titleMatch = true;
      break;
    }
  }
  if (!titleMatch) {
    for (const t of ICP.titles.warm) {
      if (title.includes(t)) {
        score += Math.round(ICP.weights.title * 0.625);
        signals.push('Cargo relevante: ' + t);
        titleMatch = true;
        break;
      }
    }
  }
  if (!titleMatch && (title.includes('vp') || title.includes('vice president') || title.includes('director'))) {
    score += Math.round(ICP.weights.title * 0.375);
    signals.push('Nivel directivo');
  }

  // Industry scoring
  let indMatch = false;
  for (const ind of ICP.industries.hot) {
    if (industry.includes(ind)) {
      score += ICP.weights.industry;
      signals.push('Industria ideal: ' + l.industry);
      indMatch = true;
      break;
    }
  }
  if (!indMatch) {
    for (const ind of ICP.industries.warm) {
      if (industry.includes(ind)) {
        score += Math.round(ICP.weights.industry * 0.6);
        signals.push('Industria relevante: ' + l.industry);
        indMatch = true;
        break;
      }
    }
  }
  if (!indMatch && industry) score += 5;
  if (!industry) risks.push('Sin industria');

  // Location scoring
  let locMatch = false;
  for (const loc of ICP.locations.premium) {
    if (location.includes(loc)) {
      score += ICP.weights.location;
      signals.push('Santiago zona premium');
      locMatch = true;
      break;
    }
  }
  if (!locMatch) {
    for (const loc of ICP.locations.standard) {
      if (location.includes(loc)) {
        score += Math.round(ICP.weights.location * 0.667);
        signals.push('Chile');
        locMatch = true;
        break;
      }
    }
  }
  if (!locMatch) risks.push('Ubicacion no clara');

  // Data quality
  if (l.company && l.company.length > 1) score += 5;
  else risks.push('Sin empresa');
  if (l.companyUrl) { score += 5; signals.push('Website disponible'); }

  // Category
  let category;
  if (score >= ICP.thresholds.hot) category = 'HOT';
  else if (score >= ICP.thresholds.warm) category = 'WARM';
  else if (score >= ICP.thresholds.nurture) category = 'NURTURE';
  else category = 'SKIP';

  // Confidence
  let confidence = 0.5;
  if (l.company && l.industry && l.companyUrl) confidence = 0.8;
  if (titleMatch && confidence >= 0.8) confidence = 0.9;

  return {
    json: {
      fullName: l.fullName || '',
      jobTitle: l.jobTitle || l.headline || '',
      company: l.company || '',
      industry: l.industry || '',
      location: l.location || '',
      linkedinUrl: l.linkedinProfileUrl || l.profileUrl || '',
      companyUrl: l.companyUrl || '',
      score,
      category,
      signals,
      risks,
      confidence,
      scoredAt: new Date().toISOString(),
      needsGemini: category === 'HOT' && (config.useGemini === true || config.useGemini === 'true')
    }
  };
}

// Score all leads from input
const leads = $input.first().json;
const items = Array.isArray(leads) ? leads : [leads];
const results = items.map(scoreLead);

// Sort by score descending
results.sort((a, b) => b.json.score - a.json.score);

return results;

// Only pass through HOT leads that need Gemini
const items = $input.all().filter(item => item.json.needsGemini === true);
if (items.length === 0) {
  return [{ json: { skip: true, reason: 'No HOT leads need Gemini' } }];
}
return items;

