const items = $input.all();
const results = [];
for (const item of items) {
  const lead = item.json;
  if (lead.skip) continue;

  // Try to extract Gemini response
  let aiData = {};
  try {
    const candidates = lead.candidates || [];
    if (candidates.length > 0) {
      const text = candidates[0].content.parts[0].text;
      aiData = JSON.parse(text);
    }
  } catch (e) {
    // Gemini failed, keep ICP score only
  }

  results.push({
    json: {
      ...lead,
      aiScore: aiData.aiScore || null,
      aiReasoning: aiData.reasoning || '',
      aiApproach: aiData.suggested_approach || '',
      aiConfidence: aiData.confidence || null,
      geminiReviewed: !!aiData.aiScore
    }
  });
}
return results.length > 0 ? results : [{ json: { empty: true } }];

const items = $input.all();
const rows = [];
for (const item of items) {
  const l = item.json;
  if (l.empty || l.skip) continue;
  rows.push({
    json: {
      empresa: l.company || '',
      contacto: l.fullName || '',
      cargo: l.jobTitle || '',
      email: l.email || '',
      linkedin: l.linkedinUrl || '',
      website: l.companyUrl || '',
      industria: l.industry || '',
      ubicacion: l.location || '',
      source: 'PhantomBuster',
      score: l.score || 0,
      categoria: l.category || '',
      status: l.category === 'HOT' ? 'Prioridad' : 'Nuevo',
      fecha: new Date().toISOString().substring(0, 10),
      aiScore: l.aiScore || '',
      aiReasoning: l.aiReasoning || '',
      aiApproach: l.aiApproach || ''
    }
  });
}
return rows.length > 0 ? rows : [{ json: { empty: true } }];

